'use strict';
const menu=document.querySelector('.menu-toggle');
const nav=document.querySelector('#navigation');
const closeMenu=()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Ouvrir le menu');nav.classList.remove('open')};
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');nav.classList.toggle('open',open)});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus()}});
const scenes={
 direction:{label:'CENTRE DE PILOTAGE',title:'Savoir où concentrer votre attention.',copy:'Consultez les priorités, la progression des projets et les éléments qui attendent une décision.',stats:[['08','Projets actifs'],['03','Décisions à prendre'],['12','Actions planifiées']],items:['Consulter les échéances de la semaine','Répartir les missions entre les équipes','Retrouver les devis à valider']},
 operations:{label:'OPÉRATIONS & INTERVENTIONS',title:'Du besoin client à la mission sur le terrain.',copy:'Préparez les interventions, affectez les tâches et gardez une trace des étapes et du matériel mobilisé.',stats:[['05','Missions planifiées'],['02','Équipes mobilisées'],['04','Équipements réservés']],items:['Préparer une intervention réseau chez un client fictif','Attribuer les tâches de maintenance à l’équipe technique','Vérifier les livrables et les pièces du dossier']},
 clients:{label:'RELATION CLIENT',title:'Chaque relation mérite un suivi clair.',copy:'Reliez les contacts, les opportunités, les projets et les documents pour retrouver l’histoire de chaque dossier.',stats:[['06','Contacts à suivre'],['03','Propositions en cours'],['02','Validations attendues']],items:['Retrouver le besoin d’un prospect fictif','Préparer une proposition et planifier la relance','Partager les livrables dans le portail client']},
 finance:{label:'FINANCE & DOCUMENTS',title:'Du devis au paiement, gardez une trace.',copy:'Suivez les documents commerciaux, les échéances et les pièces justificatives, dans le contexte de chaque projet.',stats:[['04','Devis préparés'],['02','Factures à suivre'],['03','Dépenses à valider']],items:['Retrouver les documents d’une intervention fictive','Suivre une échéance et enregistrer un paiement','Exporter un document aux couleurs MIRS']}
};
const tabs=[...document.querySelectorAll('[data-scene]')];
function selectTab(tab){const scene=scenes[tab.dataset.scene];tabs.forEach(item=>{item.setAttribute('aria-selected',String(item===tab));item.tabIndex=item===tab?0:-1});document.querySelector('#tour-panel').setAttribute('aria-labelledby',tab.id);document.querySelector('.scene-label').textContent=scene.label;document.querySelector('#scene-title').textContent=scene.title;document.querySelector('#scene-copy').textContent=scene.copy;const stats=document.querySelector('#scene-stats');stats.replaceChildren(...scene.stats.map(([value,label])=>{const node=document.createElement('div'),b=document.createElement('b'),span=document.createElement('span');b.textContent=value;span.textContent=label;node.append(b,span);return node}));const items=document.querySelector('#scene-items');items.replaceChildren(...scene.items.map(value=>{const li=document.createElement('li'),check=document.createElement('span');check.textContent='✓';li.append(check,document.createTextNode(value));return li}))}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%tabs.length;if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();selectTab(tabs[next]);tabs[next].focus()}})});
const dialog=document.querySelector('#legal-dialog');document.querySelector('#legal-open').addEventListener('click',()=>dialog.showModal());document.querySelector('#legal-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()}});
document.querySelector('#year').textContent=String(new Date().getFullYear());
